input.command:
# prod dim table meta + audit clues; test audit if accessible
mysql --defaults-file=.claude/database/my.cnf.prod -e "
SHOW CREATE TABLE dim.dim_channel_info_all;
SELECT COUNT(*) cnt FROM dim.dim_channel_info_all;
" 2>&1 | head -60

mysql --defaults-file=.claude/database/my.cnf.test -e "
SELECT COUNT(*) cnt FROM dim.dim_channel_info_all;
SHOW TABLES FROM dim LIKE '%channel%audit%';
SHOW TABLES FROM dim LIKE '%channel%';
SHOW TABLES FROM information_schema LIKE '%';
" 2>&1 | head -40

# search audit mentions in repo
rg -n "172\.31\.9\.165|dim_channel_info_all" --glob '*.{md,sql,py,yml,yaml,json}' -g '!**/node_modules/**' 2>/dev/null | head -40

# see if system_channel_info exists on test/prod SR or known elsewhere
mysql --defaults-file=.claude/database/my.cnf.test -e "
SHOW TABLES FROM dim LIKE '%channel%';
SHOW TABLES FROM ods LIKE '%channel%' 2>/dev/null;
SHOW TABLES FROM dw LIKE '%channel%' 2>/dev/null;
" 2>&1 | head -40
mysql --defaults-file=.claude/database/my.cnf.prod -e "
SHOW TABLES FROM dim LIKE '%channel%';
" 2>&1 | head -20
bash ~/.dc-platform/scripts/lookup-rules.sh "system_channel_info|渠道维全量" 2>&1 | head -25

